#!/usr/bin/env node
'use strict';
// Can someone who did not build this service run it?
//
// The suite covered getting code to production and nothing about it being
// there. This is the deterministic slice of that: an OPERATIONS.md with four
// sections that have real content, plus the two operability properties a
// repository can actually show — a health endpoint and structured logging.
//
// Deliberately NOT attempted: whether the alerts fire, whether the runbook
// is correct, whether the SLO is met. Those need a running system and a
// history, neither of which is in a checkout. Where this cannot tell, it
// reports not_evaluated rather than guessing — a missing answer must never
// read as a good one.
//
// Usage: node check-operability.js --root <dir> [--strict] [--out <file>] [--no-write]

const path = require('path');
const fs = require('fs');
const { corePaths } = require('./resolve-core.cjs');
const core = corePaths();
const { parseArgs } = require(path.join(core.lib, 'args.cjs'));
const { check, runCli, readText, sectionHasContent } = require(path.join(core.lib, 'report.cjs'));
const { classify } = require(path.join(core.lib, 'classify.cjs'));
const registry = require(core.registry);

const REQUIRED_SECTIONS = ['Signals', 'Alerts', 'Failure modes', 'Recovery'];
const SOURCE_EXT = /\.(c|m)?[jt]sx?$|\.(py|go|rb|rs|java)$/;

// A health or readiness endpoint under any of the usual spellings. This is
// the one operability affordance that is unambiguous in source: either a
// route answers "are you alive" or nothing does.
const HEALTH_ROUTE = /['"`]\/(healthz|health|readyz|ready|livez|live|_health|status)['"`]|\bhealth_?check\b|actuator\/health/i;

// Structured logging means fields, not a sentence. A logger library or a
// call carrying an object both count; a bare console.log does not, which is
// the distinction that decides whether an incident can be traced.
const STRUCTURED_LOGGER = /\b(pino|winston|bunyan|zerolog|logrus|structlog|slog|zap|serilog)\b/i;
// Either a logging call carrying fields, or JSON written to the log stream
// by hand. The second form was a false negative found on this suite's own
// fixture: `process.stdout.write(JSON.stringify({...}))` is structured
// logging by any definition that matters to an incident.
// The JSON may be wrapped — a template literal, a concatenation, a helper —
// so the match allows a short run of characters between the write and the
// serialisation rather than demanding they be adjacent. Adjacency was a
// false negative on this suite's own fixture the moment the newline moved
// into a template string.
const STRUCTURED_CALL = /\b(log|logger)\.(info|warn|error|debug)\s*\(\s*\{|(?:stdout|stderr)\.write\s*\([^)]{0,40}JSON\.stringify|\bconsole\.(log|info|warn|error)\s*\([^)]{0,40}JSON\.stringify/;
const BARE_CONSOLE = /\bconsole\.(log|error|warn)\s*\(/;

function sourceFiles(cls) {
  const out = [];
  for (let i = 0; i < cls.rel.length; i++) {
    if (!SOURCE_EXT.test(cls.rel[i])) continue;
    const text = cls.readFileSafe(i);
    if (text !== null) out.push({ rel: cls.rel[i], text });
  }
  return out;
}

function run(root) {
  const cls = classify(root, { evidenceDir: registry.evidenceDir });
  const checks = [];

  // Nothing runs, nothing to operate.
  if (!cls.serverPresent) {
    checks.push(check('O-scope', 'pass', 'no server detected; operability gate not required'));
    return checks;
  }

  const docPath = path.join(root, 'OPERATIONS.md');
  if (!fs.existsSync(docPath)) {
    checks.push(check('O-operations-doc', 'fail',
      'no OPERATIONS.md — a running service with no written signals, alerts, failure modes or recovery is operable only by whoever built it'));
    for (const section of REQUIRED_SECTIONS) {
      checks.push(check(`O-section-${section.toLowerCase().replace(/\s+/g, '-')}`, 'not_evaluated', 'no OPERATIONS.md to inspect'));
    }
  } else {
    const text = readText(docPath);
    checks.push(check('O-operations-doc', 'pass', 'OPERATIONS.md'));
    for (const section of REQUIRED_SECTIONS) {
      const id = `O-section-${section.toLowerCase().replace(/\s+/g, '-')}`;
      checks.push(sectionHasContent(text, section)
        ? check(id, 'pass', section)
        : check(id, 'fail', `OPERATIONS.md section "${section}" is missing or empty`));
    }
  }

  const files = sourceFiles(cls);
  if (files.length === 0) {
    checks.push(check('O-health-endpoint', 'not_evaluated', 'no readable source files to scan'));
    checks.push(check('O-structured-logs', 'not_evaluated', 'no readable source files to scan'));
    return checks;
  }

  const health = files.find((f) => HEALTH_ROUTE.test(f.text));
  checks.push(health
    ? check('O-health-endpoint', 'pass', `health/readiness route in ${health.rel}`)
    : check('O-health-endpoint', 'fail',
        'no health or readiness endpoint found; a deploy gate cannot observe health it cannot ask for'));

  const structured = files.find((f) => STRUCTURED_LOGGER.test(f.text) || STRUCTURED_CALL.test(f.text));
  const bareOnly = files.filter((f) => BARE_CONSOLE.test(f.text));
  if (structured) {
    checks.push(check('O-structured-logs', 'pass', `structured logging in ${structured.rel}`));
  } else if (bareOnly.length > 0) {
    checks.push(check('O-structured-logs', 'fail',
      `only unstructured console output found (e.g. ${bareOnly[0].rel}); an incident cannot be traced through prose`));
  } else {
    checks.push(check('O-structured-logs', 'not_evaluated',
      'no logging calls recognised; whether this service emits anything could not be determined from source'));
  }

  if (cls.truncated) {
    checks.push(check('O-scan-completeness', 'not_evaluated',
      'file walk hit the safety cap; endpoint and logging detection may be incomplete'));
  }
  return checks;
}

module.exports = { run };

if (require.main === module) {
  // Selected by id: this skill produces two reports.
  const artifact = registry.artifacts.find((a) => a.id === 'operability-report');
  runCli({
    skill: 'release-engineering',
    reportFile: path.basename(artifact.file),
    evidenceDir: registry.evidenceDir,
    runFn: run,
    argv: process.argv.slice(2),
    parseArgs,
  });
}
#!/usr/bin/env node
'use strict';
// Does the project's declared way of running itself actually resolve?
//
// This is the deterministic floor under product-acceptance's A-runtime,
// which is an ASSERTION by an independent acceptor ("I ran it and the
// critical path worked") with nothing mechanical behind it. Nothing here
// proves the product works — it proves the commands a human would type are
// not pointing at files that don't exist. Found by eval: a build declared
// `"test": "node --test test/"` and shipped no test/ directory, so the
// command failed instantly and no check in the suite noticed.
//
// DELIBERATELY DOES NOT EXECUTE ANYTHING by default. Running `npm test` in
// an audited project means executing whatever that project wrote, which is
// not a thing this suite does anywhere else (see SECURITY.md). --run is
// opt-in, off in acceptance, and documented as executing target code.
//
// Usage: node check-smoke.js --root <dir> [--strict] [--out <file>] [--no-write]

const path = require('path');
const fs = require('fs');
const { spawnSync } = require('child_process');
const { corePaths } = require('./resolve-core.cjs');
const core = corePaths();
const { parseArgs } = require(path.join(core.lib, 'args.cjs'));
const { check, runCli } = require(path.join(core.lib, 'report.cjs'));
const registry = require(core.registry);

// npm's own `npm init` placeholder. A project carrying it has no test
// command, it just looks like it does — worth naming separately from
// "no test script at all" because the two get fixed differently.
const NPM_PLACEHOLDER = /no test specified/i;

// A token is only treated as a local path when it is unambiguous: an
// explicit ./ or ../ prefix, a source-file extension, or the argument to
// node's --test. Anything with a shell metacharacter, a glob, or a
// variable is left alone — a false "missing file" here would be worse
// than a miss, because the fix for it is unclear to the person reading it.
const AMBIGUOUS = /[*?$`|&<>(){}[\]]|^-|^\$/;
const SOURCE_EXT = /\.(m|c)?[jt]sx?$/;

function localPathTokens(command) {
  const tokens = command.split(/\s+/).filter(Boolean);
  const out = [];
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t === '--test' || t === '--import' || t === '--require') {
      const next = tokens[i + 1];
      if (next && !AMBIGUOUS.test(next)) out.push(next);
      continue;
    }
    if (AMBIGUOUS.test(t)) continue;
    if (/^\.{1,2}\//.test(t) || SOURCE_EXT.test(t)) out.push(t);
  }
  return out;
}

function exists(root, rel) {
  const clean = rel.replace(/^\.\//, '').replace(/\/$/, '');
  return fs.existsSync(path.join(root, clean));
}

function readPackageJson(root) {
  try {
    return JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
  } catch {
    return null;
  }
}

function entryPointsOf(pkg) {
  const out = [];
  if (typeof pkg.main === 'string') out.push(['main', pkg.main]);
  if (typeof pkg.module === 'string') out.push(['module', pkg.module]);
  if (typeof pkg.bin === 'string') out.push(['bin', pkg.bin]);
  else if (pkg.bin && typeof pkg.bin === 'object') {
    for (const [name, file] of Object.entries(pkg.bin)) {
      if (typeof file === 'string') out.push([`bin.${name}`, file]);
    }
  }
  return out;
}

const TEST_FILE = /(\.|_)(test|spec)\.(m|c)?[jt]sx?$|^test_.*\.py$|_test\.go$|(\.|_)(test|spec)\.py$/i;
const TEST_DIR = /(^|[\\/])(test|tests|__tests__|spec)([\\/]|$)/i;
const SKIP_DIRS = new Set(['node_modules', '.git', 'dist', 'build', 'coverage', '.next', 'vendor', 'target', '.venv', 'venv', '.claude', '.cursor', '.codex', '.agents', '.aider', '.worktrees']);
const MAX_WALK = 20000;

function findTestFiles(root) {
  const found = [];
  let seen = 0;
  (function walk(dir, rel) {
    if (found.length >= 5 || seen >= MAX_WALK) return;
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory()) {
        if (SKIP_DIRS.has(e.name)) continue;
        walk(path.join(dir, e.name), childRel);
      } else {
        seen++;
        // A file inside a test directory counts only if it is source —
        // a fixture .csv or a README in test/ is not a test.
        if (TEST_FILE.test(e.name) || (TEST_DIR.test(childRel) && SOURCE_EXT.test(e.name))) {
          found.push(childRel);
        }
      }
      if (found.length >= 5) return;
    }
  })(root, '');
  return found;
}

function run(root, opts = {}) {
  const pkg = readPackageJson(root);
  const checks = [];

  if (!pkg) {
    checks.push(check('R-scope', 'pass', 'no readable package.json; script and entry-point checks not applicable'));
    return checks;
  }

  // 1. Every declared script points at something that exists.
  const scripts = pkg.scripts && typeof pkg.scripts === 'object' ? pkg.scripts : {};
  const broken = [];
  for (const [name, command] of Object.entries(scripts)) {
    if (typeof command !== 'string') continue;
    for (const token of localPathTokens(command)) {
      if (!exists(root, token)) broken.push(`${name} -> ${token}`);
    }
  }
  checks.push(broken.length > 0
    ? check('R-script-targets', 'fail', `declared script(s) reference missing paths: ${broken.join('; ')}`)
    : check('R-script-targets', 'pass',
        `${Object.keys(scripts).length} declared script(s), all referenced paths present`));

  // 2. Entry points resolve.
  const entries = entryPointsOf(pkg);
  const missingEntries = entries.filter(([, file]) => !exists(root, file)).map(([k, f]) => `${k} -> ${f}`);
  if (entries.length === 0) {
    checks.push(check('R-entry-points', 'pass', 'no main/module/bin declared'));
  } else {
    checks.push(missingEntries.length > 0
      ? check('R-entry-points', 'fail', `declared entry point(s) missing: ${missingEntries.join('; ')}`)
      : check('R-entry-points', 'pass', `${entries.length} entry point(s) resolve`));
  }

  // 3. There is a way to run the tests at all.
  if (!scripts.test) {
    checks.push(check('R-test-command', 'fail', 'no "test" script declared; there is no stated way to run this project\'s tests'));
  } else if (NPM_PLACEHOLDER.test(scripts.test)) {
    checks.push(check('R-test-command', 'fail', `"test" script is npm's placeholder: ${scripts.test}`));
  } else {
    checks.push(check('R-test-command', 'pass', `test script: ${scripts.test}`));
  }

  // 4. A test command over an empty directory passes every check above —
  //    the path exists. Measured: all three arms of the oncall eval
  //    declared or scaffolded a test setup and none of them wrote a test.
  const testFiles = findTestFiles(root);
  checks.push(testFiles.length > 0
    ? check('R-tests-present', 'pass', `${testFiles.length} test file(s), e.g. ${testFiles[0]}`)
    : check('R-tests-present', 'fail', 'no test files found; a declared test command over an empty directory is not a test suite'));

  // 5. Opt-in execution. Never set by acceptance.
  if (opts.run && scripts.test && !NPM_PLACEHOLDER.test(scripts.test)) {
    const res = spawnSync('npm', ['test', '--silent'], {
      cwd: root, encoding: 'utf8', timeout: 300000, shell: process.platform === 'win32',
    });
    if (res.error) {
      checks.push(check('R-test-run', 'not_evaluated', `could not run npm test: ${res.error.message}`));
    } else {
      checks.push(res.status === 0
        ? check('R-test-run', 'pass', 'npm test exited 0')
        : check('R-test-run', 'fail', `npm test exited ${res.status}`));
    }
  }
  // No R-test-run check at all without --run. Emitting a standing
  // not_evaluated would pin every project at CONDITIONAL forever, and the
  // "nobody watched it run" fact is already carried by acceptance's
  // A-runtime, which is where it belongs.

  return checks;
}

module.exports = { run, localPathTokens };

if (require.main === module) {
    // Selected by id: release-engineering now produces two reports, so a
  // by-producer lookup would pick whichever came first in the registry.
  const artifact = registry.artifacts.find((a) => a.id === 'smoke-report');
  const argv = process.argv.slice(2);
  const wantsRun = argv.includes('--run');
  runCli({
    skill: 'release-engineering',
    reportFile: path.basename(artifact.file),
    evidenceDir: registry.evidenceDir,
    runFn: (root) => run(root, { run: wantsRun }),
    argv: argv.filter((a) => a !== '--run'),
    parseArgs,
  });
}
